    _precedence = {
        '|': 1, '^': 2, '&': 3,
        '+': 4, '-': 4,
        '*': 5, '/': 5, '%': 5, '#': 5,
        ':': 6,
    }

    unary_ops = {'~': '~', '_': '-'}
    binary_ops = {
        '+': '+', '-': '-', '*': '*', '/': '/', '%': '%',
        ':': '**', '&': '&', '|': '|', '^': '^', '#': '//'
    }

    def needs_parens(op, parent_op, is_right=False):
        p = _precedence.get(op, 100)
        pp = _precedence.get(parent_op, 100)
        if p < pp:
            return True
        if p == pp and is_right:
            return True
        return False

    parts = list(zip(path[::2], path[1::2]))

    result = root_str
    result_op = None

    for i, (op, arg) in enumerate(parts):
        if op == '.':
            result = result + '.' + arg
            result_op = None
