            all_args = ', '.join(arg_strs + kwarg_strs)
            result = result + '(' + all_args + ')'
            result_op = None
        elif op in unary_ops:
            result = unary_ops[op] + result
            result_op = op
        elif op in binary_ops:
            arg_repr = bbrepr(arg) if not isinstance(arg, TType) else repr(arg)
            cur_prec = _precedence.get(op, 100)
